mapper.select:
SELECT identity_id identityId,member_id memberId,identity_type identityType,masked_value maskedValue,
  state,key_version keyVersion,bound_at createdAt FROM mbr_identity
WHERE tenant_id=#{tenantId} AND identity_id=#{identityId}

SELECT consent_id consentId,member_id memberId,purpose_code purposeCode,policy_version policyVersion,
  state,evidence_sha256 evidenceSha256,occurred_at occurredAt FROM mbr_consent_ledger
WHERE tenant_id=#{tenantId} AND consent_id=#{consentId}

SELECT request_id requestId,member_id memberId,request_type requestType,state,version,
  submitted_at submittedAt,completed_at completedAt FROM mbr_privacy_request
WHERE tenant_id=#{tenantId} AND request_id=#{requestId}

SELECT link_id linkId,source_member_id sourceMemberId,target_member_id targetMemberId,action,
  occurred_at occurredAt FROM mbr_member_link_ledger WHERE tenant_id=#{tenantId} AND link_id=#{linkId}
ORDER BY occurred_at DESC,link_ledger_id DESC LIMIT 1

SELECT request_sha256 requestSha256,aggregate_id aggregateId,result_sha256 resultSha256,
  CAST(result_json AS CHAR) resultJson FROM mbr_command_result
WHERE tenant_id=#{tenantId} AND command_type=#{commandType} AND idempotency_key=#{idempotencyKey}
